const tg=window.Telegram?.WebApp;
const S={initData:tg?.initData||'',page:'home',settings:{},maps:{},draft:null,txFilters:{},txOffset:0,txLimit:80,importRows:null};
const $=s=>document.querySelector(s), view=$('#view'), shell=$('#shell'), gate=$('#login');
const fa=n=>Number(n||0).toLocaleString('fa-IR'), money=n=>`${fa(n)} تومان`, tehranIso=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tehran',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={home:'خانه',transactions:'تراکنش‌ها',projects:'پروژه‌ها',reports:'گزارش',settings:'تنظیمات'};
function toast(t){const el=$('#toast');el.textContent=t;el.classList.remove('hidden');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.add('hidden'),2600)}
function modal(title,html){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;$('#modal').classList.remove('hidden')}
function closeModal(){$('#modal').classList.add('hidden');$('#modalBody').innerHTML=''}
$('#modalClose').onclick=closeModal;$('.modal-backdrop').onclick=closeModal;
function headers(extra={}){return{'x-telegram-init-data':S.initData,...extra}}
async function api(path,opt={}){const init={credentials:'same-origin',...opt,headers:{...headers(),...(opt.body&&!(opt.body instanceof FormData)?{'content-type':'application/json'}:{}),...(opt.headers||{})}};if(init.body&&!(init.body instanceof FormData)&&typeof init.body!=='string')init.body=JSON.stringify(init.body);const r=await fetch(path,init);const j=await r.json().catch(()=>({ok:false,error:{message:'پاسخ سرور معتبر نیست.'}}));if(!r.ok||!j.ok){if(r.status===401)showLogin();throw new Error(j.error?.message||'عملیات انجام نشد.')}return j.data??j}
async function fetchBlob(path,opt={}){const r=await fetch(path,{credentials:'same-origin',...opt,headers:{...headers(),...(opt.headers||{})}});if(!r.ok){if(r.status===401)showLogin();throw new Error('دریافت فایل انجام نشد.')}return r.blob()}
function downloadBlob(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.append(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},1000)}
function showLogin(){shell.classList.add('hidden');gate.classList.remove('hidden')}
async function login(){const err=$('#loginError');err.textContent='';if(!S.initData){err.textContent='این Mini App فقط از داخل Telegram قابل ورود است.';return}try{const r=await fetch('/api/auth/login',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify({initData:S.initData,pin:$('#pin').value,timeout:$('#timeout').value})});const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error?.message||'ورود ناموفق بود.');$('#pin').value='';gate.classList.add('hidden');shell.classList.remove('hidden');await bootstrap()}catch(e){err.textContent=e.message}}
$('#loginBtn').onclick=login;$('#pin').addEventListener('keydown',e=>{if(e.key==='Enter')login()});
async function bootstrap(){tg?.ready();tg?.expand();try{tg?.setHeaderColor('#0b0f17');tg?.setBackgroundColor('#0b0f17')}catch{}S.settings=await api('/api/settings');await route(S.page)}
async function route(page){S.page=page;$('#pageTitle').textContent=labels[page]||page;document.querySelectorAll('.bottom-nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));view.innerHTML='<div class="empty">در حال بارگذاری…</div>';try{if(page==='home')await renderHome();else if(page==='transactions')await renderTransactions();else if(page==='projects')await renderProjects();else if(page==='reports')await renderReports();else await renderSettings()}catch(e){view.innerHTML=`<div class="empty danger-text">${esc(e.message)}</div>`}}
document.querySelectorAll('.bottom-nav button').forEach(b=>b.onclick=()=>route(b.dataset.page));$('#fab').onclick=()=>transactionForm();$('#moreBtn').onclick=()=>moreMenu();
function txRow(t){const icon=t.type==='income'?'↙️':t.type==='transfer'?'↔️':t.type==='refund'?'↩️':'↗️';return `<div class="row clickable" data-tx="${esc(t.transaction_id)}"><div class="row-main"><div class="row-icon">${icon}</div><div><h3>${esc(t.description||typeFa(t.type))}${t.is_starred==='true'?' ⭐':''}</h3><p>${esc(t.transaction_date||'')} ${t.fee_amount?`• کارمزد ${money(t.fee_amount)}`:''}</p></div></div><div class="amount ${t.type==='income'||t.type==='refund'?'positive':t.type==='transfer'?'':'negative'}">${t.type==='income'||t.type==='refund'?'+':t.type==='transfer'?'':'−'}${money(t.amount)}</div></div>`}
function typeFa(t){return({expense:'خرج',income:'درآمد',transfer:'انتقال',installment_payment:'پرداخت قسط',debt:'بدهی',receivable:'طلب',refund:'بازپرداخت',adjustment:'اصلاح مانده'})[t]||t}
function sourceFa(v){return({telegram:'تلگرام',mini_app:'مینی‌اپ',ai:'هوش مصنوعی',bank_import:'ورودی بانکی',installment:'قسط',recurring:'تکرارشونده',manual:'دستی',other:'سایر'})[v]||v}
function inboxTypeFa(v){return({bank_import:'ورودی بانکی',receipt_ai:'استخراج فیش',ai_action:'اقدام هوش مصنوعی',draft:'پیش‌نویس',duplicate_suspect:'تکراری مشکوک',file:'فایل',error:'خطای نیازمند بررسی',reminder_sent:'یادآور ارسال‌شده'})[v]||'مورد بررسی'}
function enumFa(v){return({'Bank account':'حساب بانکی',Card:'کارت',Cash:'نقد',Wallet:'کیف پول',Other:'سایر',expense:'خرج',income:'درآمد',both:'هر دو',active:'فعال',completed:'تکمیل‌شده',archived:'آرشیوشده',overdue:'سررسیدگذشته',daily:'روزانه',weekly:'هفتگی',monthly:'ماهانه',yearly:'سالانه',custom:'سفارشی',global:'کلی',category:'دسته‌بندی',project:'پروژه',transfer:'انتقال',true:'بله',false:'خیر'})[v]||v}
async function renderHome(){
  const d=await api('/api/dashboard');
  const upcoming=(d.upcoming_installments||[]).slice(0,3);
  view.innerHTML=`<section class="grid stats"><div class="card stat"><small>خرج ماه</small><strong class="negative">${money(d.summary.expense)}</strong></div><div class="card stat"><small>درآمد ماه</small><strong class="positive">${money(d.summary.income)}</strong></div><div class="card stat"><small>کارمزد</small><strong>${money(d.summary.fees)}</strong></div><div class="card stat"><small>خالص</small><strong>${money(d.summary.net)}</strong></div></section>
<section class="section card"><div class="section-head"><h2>روند هزینه</h2><span class="badge">این ماه</span></div><canvas id="homeChart" class="chart"></canvas></section>
<section class="section"><div class="section-head"><h2>حساب‌ها</h2><button class="ghost" data-action="accounts">مدیریت</button></div><div class="chips">${d.accounts.map(a=>`<button class="card clickable home-account" data-id="${esc(a.account_id)}" style="min-width:150px;text-align:right"><small class="muted">${esc(a.name)}</small><strong style="display:block;margin-top:7px">${money(a.balance)}</strong></button>`).join('')||'<span class="muted">حسابی تعریف نشده است.</span>'}</div></section>
${budgetCards(d.budgets)}
${upcoming.length?`<section class="section"><div class="section-head"><h2>اقساط پیش رو</h2><button class="ghost" data-action="installments">همه</button></div><div class="list">${upcoming.map(x=>`<div class="row clickable" data-inst="${esc(x.installment_id)}"><div><h3>${esc(x.title)}</h3><p>روز سررسید: ${fa(x.due_day)}</p></div><b>${money(x.default_installment_amount)}</b></div>`).join('')}</div></section>`:''}
<section class="section"><div class="section-head"><h2>آخرین تراکنش‌ها</h2><button class="ghost" data-action="alltx">همه</button></div><div class="list">${d.recent.map(txRow).join('')||'<div class="empty">هنوز تراکنشی نیست.</div>'}</div></section>
<section class="grid two"><button class="menu-item" data-action="inbox">📥<b>صندوق ورودی</b><small>${fa(d.inbox_count)} مورد منتظر بررسی</small></button><button class="menu-item" data-action="people">👥<b>طلب‌های باز</b><small>${money(d.outstanding_receivables)}</small></button></section>`;
  drawLine($('#homeChart'),Object.values(d.summary.daily||{}));bindTxRows();
  view.querySelector('[data-action=accounts]')?.addEventListener('click',()=>manageEntity('accounts'));
  view.querySelector('[data-action=alltx]')?.addEventListener('click',()=>{S.txOffset=0;route('transactions')});
  view.querySelector('[data-action=inbox]')?.addEventListener('click',showInbox);
  view.querySelector('[data-action=people]')?.addEventListener('click',()=>manageEntity('people'));
  view.querySelector('[data-action=installments]')?.addEventListener('click',manageInstallments);
  view.querySelectorAll('.home-account').forEach(b=>b.onclick=()=>accountDetail(b.dataset.id));
  view.querySelectorAll('[data-inst]').forEach(b=>b.onclick=()=>installmentDetail(b.dataset.inst));
}
function budgetCards(budgets){
  const rows=(budgets||[]).filter(b=>String(b.period||'monthly').toLowerCase()==='monthly');
  if(!rows.length)return'';
  return `<section class="section"><div class="section-head"><h2>بودجه</h2></div>${rows.slice(0,4).map(b=>{const p=Math.max(0,Math.min(100,Math.round(Number(b.percent||0))));const title=b.scope_type==='global'?'بودجه ماهانه':b.scope_type==='category'?'بودجه دسته':'بودجه پروژه';return`<div class="card section"><div class="section-head"><span>${title}</span><b>${fa(b.percent||0)}٪</b></div><div class="progress"><i style="width:${p}%"></i></div><p class="muted">${money(b.used)} از ${money(b.amount)} • مانده ${money(b.remaining)}</p></div>`}).join('')}</section>`;
}
function drawLine(canvas,vals){if(!canvas)return;const ctx=canvas.getContext('2d'),dpr=devicePixelRatio||1,w=canvas.clientWidth,h=canvas.clientHeight;canvas.width=w*dpr;canvas.height=h*dpr;ctx.scale(dpr,dpr);ctx.clearRect(0,0,w,h);const v=vals.length?vals:[0],max=Math.max(...v,1);ctx.strokeStyle='#6ee7b7';ctx.lineWidth=2.5;ctx.beginPath();v.forEach((x,i)=>{const px=v.length===1?w/2:12+i*(w-24)/(v.length-1),py=h-16-(x/max)*(h-32);i?ctx.lineTo(px,py):ctx.moveTo(px,py)});ctx.stroke();ctx.fillStyle='#97a4b7';ctx.font='11px Tahoma';ctx.fillText(money(max),8,13)}
function bindTxRows(){view.querySelectorAll('[data-tx]').forEach(x=>x.onclick=()=>transactionDetail(x.dataset.tx))}
async function loadEntities(name,all=false){const r=await api(`/api/entities/${name}?limit=500${all?'&archived=all':''}`);return r.items}
async function entityMaps(){const [accounts,categories,people,projects,tags,merchants,installments]=await Promise.all(['accounts','categories','people','projects','tags','merchants','installments'].map(x=>loadEntities(x)));S.maps={accounts,categories,people,projects,tags,merchants,installments};return S.maps}
function optionRows(rows,id,name,selected=''){return`<option value="">—</option>`+rows.map(x=>`<option value="${esc(x[id])}" ${String(x[id])===String(selected)?'selected':''}>${esc(x[name]||x.title)}</option>`).join('')}
async function renderTransactions(append=false){
  if(!append)S.txOffset=0;
  const q=new URLSearchParams(S.txFilters);q.set('limit',String(S.txLimit));q.set('offset',String(S.txOffset));
  const r=await api('/api/transactions?'+q),items=r.items||[];
  if(!append){
    view.innerHTML=`<div class="toolbar"><input id="txSearch" value="${esc(S.txFilters.q||'')}" aria-label="جستجو"><button id="filterBtn" class="secondary">فیلتر</button></div><div class="chips"><button class="chip ${!S.txFilters.type?'active':''}" data-type="">همه</button>${['expense','income','transfer','installment_payment','receivable','debt','refund','adjustment'].map(t=>`<button class="chip ${S.txFilters.type===t?'active':''}" data-type="${t}">${typeFa(t)}</button>`).join('')}</div><div class="section-head" style="margin-top:14px"><span class="muted" id="txCount">${fa(r.total)} نتیجه</span><button id="exportCurrent" class="ghost">خروجی</button></div><div class="list" id="txList">${items.map(txRow).join('')||'<div class="empty">تراکنشی پیدا نشد.</div>'}</div><button id="txMore" class="secondary wide section">نمایش بیشتر</button>`;
    let timer;$('#txSearch').oninput=e=>{clearTimeout(timer);timer=setTimeout(()=>{S.txFilters.q=e.target.value;S.txOffset=0;renderTransactions()},350)};
    view.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{if(b.dataset.type)S.txFilters.type=b.dataset.type;else delete S.txFilters.type;S.txOffset=0;renderTransactions()});
    $('#filterBtn').onclick=transactionFilters;$('#exportCurrent').onclick=exportMenu;
  }else if(items.length){$('#txList').insertAdjacentHTML('beforeend',items.map(txRow).join(''))}
  bindTxRows();
  const more=$('#txMore');if(more){more.classList.toggle('hidden',S.txOffset+items.length>=r.total);more.onclick=()=>{S.txOffset+=S.txLimit;renderTransactions(true)}}
}
async function transactionFilters(){
  await entityMaps();const f=S.txFilters;
  modal('فیلتر تراکنش‌ها',`<div class="form filters"><label>از تاریخ میلادی<input id="fFrom" type="date" value="${esc(f.from||'')}"></label><label>تا تاریخ میلادی<input id="fTo" type="date" value="${esc(f.to||'')}"></label><label>حساب<select id="fAccount">${optionRows(S.maps.accounts,'account_id','name',f.account_id)}</select></label><label>دسته<select id="fCategory">${optionRows(S.maps.categories,'category_id','name',f.category_id)}</select></label><label>شخص<select id="fPerson">${optionRows(S.maps.people,'person_id','name',f.person_id)}</select></label><label>پروژه<select id="fProject">${optionRows(S.maps.projects,'project_id','name',f.project_id)}</select></label><label>فروشنده<select id="fMerchant">${optionRows(S.maps.merchants,'merchant_id','name',f.merchant_id)}</select></label><label>برچسب<select id="fTag">${optionRows(S.maps.tags,'tag_id','name',f.tag_id)}</select></label><label>حداقل مبلغ<input id="fMin" inputmode="numeric" value="${esc(f.min_amount??'')}"></label><label>حداکثر مبلغ<input id="fMax" inputmode="numeric" value="${esc(f.max_amount??'')}"></label><label>وضعیت<select id="fStatus"><option value="">همه</option><option value="confirmed" ${f.status==='confirmed'?'selected':''}>قطعی</option><option value="pending" ${f.status==='pending'?'selected':''}>در انتظار</option></select></label><label>منبع<select id="fSource"><option value="">همه</option>${['telegram','mini_app','ai','bank_import','installment','recurring','manual','other'].map(x=>`<option value="${x}" ${f.source===x?'selected':''}>${sourceFa(x)}</option>`).join('')}</select></label><label>ویژگی<select id="fFlags"><option value="">همه</option><option value="fee">دارای کارمزد</option><option value="receipt">دارای فیش</option><option value="starred">ستاره‌دار</option><option value="installment">قسط</option><option value="debt">بدهی/طلب</option></select></label></div><div class="actions"><button id="applyFilters" class="primary">اعمال</button><button id="clearFilters" class="secondary">پاک کردن</button></div>`);
  $('#applyFilters').onclick=()=>{S.txFilters={...S.txFilters,from:$('#fFrom').value,to:$('#fTo').value,account_id:$('#fAccount').value,category_id:$('#fCategory').value,person_id:$('#fPerson').value,project_id:$('#fProject').value,merchant_id:$('#fMerchant').value,tag_id:$('#fTag').value,min_amount:$('#fMin').value,max_amount:$('#fMax').value,status:$('#fStatus').value,source:$('#fSource').value};Object.keys(S.txFilters).forEach(k=>{if(S.txFilters[k]==='')delete S.txFilters[k]});for(const k of ['has_fee','has_receipt','starred','installment','debt_receivable'])delete S.txFilters[k];const flag=$('#fFlags').value;if(flag==='fee')S.txFilters.has_fee=true;if(flag==='receipt')S.txFilters.has_receipt=true;if(flag==='starred')S.txFilters.starred=true;if(flag==='installment')S.txFilters.installment=true;if(flag==='debt')S.txFilters.debt_receivable=true;closeModal();S.txOffset=0;renderTransactions()};
  $('#clearFilters').onclick=()=>{S.txFilters={};S.txOffset=0;closeModal();renderTransactions()};
}
async function transactionDetail(id){const d=await api(`/api/transactions/${id}`),t=d.transaction;modal('جزئیات تراکنش',`<div class="card"><div class="section-head"><span class="badge">${typeFa(t.type)}</span><b class="amount">${money(t.amount)}</b></div><h3>${esc(t.description||'بدون شرح')}</h3><p class="muted">${esc(t.transaction_date)} • ${esc(sourceFa(t.source))}</p>${t.fee_amount?`<p>کارمزد: ${money(t.fee_amount)}</p>`:''}${t.note?`<p>${esc(t.note)}</p>`:''}<details><summary>جزئیات بیشتر</summary><p>شماره پیگیری: ${esc(t.tracking_number||'—')}</p><p>شماره مرجع: ${esc(t.reference_number||'—')}</p><p>شناسه بانکی: ${esc(t.bank_transaction_id||'—')}</p><p>شناسه تراکنش: ${esc(t.transaction_id)}</p></details></div><div class="section"><div class="section-head"><h3>فیش‌ها</h3><button id="addReceipt" class="ghost">افزودن</button></div><div id="receiptGrid" class="receipt-grid"></div></div><div class="actions"><button id="editTx" class="secondary">ویرایش</button><button id="starTx" class="secondary">${t.is_starred==='true'?'حذف ستاره':'ستاره'}</button><button id="deleteTx" class="danger">انتقال به سطل زباله</button></div>`);await renderReceipts(d.receipts);$('#editTx').onclick=()=>transactionForm({...t,tag_ids:d.tags.map(x=>x.tag_id)});$('#starTx').onclick=async()=>{await api(`/api/transactions/${id}`,{method:'PATCH',body:{is_starred:t.is_starred!=='true'}});toast('ذخیره شد.');closeModal();route(S.page)};$('#deleteTx').onclick=async()=>{if(!confirm('تراکنش به سطل زباله منتقل شود؟'))return;await api(`/api/transactions/${id}`,{method:'DELETE'});toast('به سطل زباله منتقل شد.');closeModal();route(S.page)};$('#addReceipt').onclick=()=>pickReceiptFor(id)}
async function renderReceipts(items){
  const grid=$('#receiptGrid');if(!grid)return;if(!items.length){grid.innerHTML='<span class="muted">فیشی ثبت نشده است.</span>';return}grid.innerHTML='';
  for(const r of items){
    const wrap=document.createElement('div');wrap.className='card';wrap.style.padding='6px';wrap.innerHTML=`<img><div class="actions"><button class="ghost webp">WebP</button><button class="ghost jpg">JPG</button><button class="secondary rai">AI</button><button class="danger del">×</button></div>`;grid.append(wrap);
    try{let blob=await fetchBlob(`/api/receipts/${r.receipt_id}?thumb=true`);if(r.mime_type!=='image/webp'){await optimizeExistingReceipt(r.receipt_id).catch(()=>{});blob=await fetchBlob(`/api/receipts/${r.receipt_id}?thumb=true`).catch(()=>blob)}const u=URL.createObjectURL(blob);wrap.querySelector('img').src=u;wrap.querySelector('img').onclick=()=>window.open(u,'_blank')}catch{}
    wrap.querySelector('.webp').onclick=()=>downloadReceipt(r.receipt_id,'webp');wrap.querySelector('.jpg').onclick=()=>downloadReceipt(r.receipt_id,'jpg');wrap.querySelector('.rai').onclick=()=>receiptAiReview(r.receipt_id);wrap.querySelector('.del').onclick=async()=>{if(confirm('فیش حذف شود؟')){await api(`/api/receipts/${r.receipt_id}`,{method:'DELETE'});wrap.remove()}};
  }
}
async function receiptAiReview(id){
  try{const x=await api(`/api/receipts/${id}/ai`,{method:'POST'});modal('پیشنهاد استخراج فیش',`<div class="form"><label>مبلغ<input id="raAmount" inputmode="numeric" value="${esc(x.amount??'')}"></label><label>تاریخ<input id="raDate" value="${esc(x.date||'')}"></label><label>فروشنده<input id="raMerchant" value="${esc(x.merchant||'')}"></label><label>کارمزد<input id="raFee" inputmode="numeric" value="${esc(x.fee??0)}"></label><label>شماره پیگیری<input id="raTracking" value="${esc(x.tracking_number||'')}"></label><label>شماره مرجع<input id="raReference" value="${esc(x.reference_number||'')}"></label><label>شرح<input id="raDesc" value="${esc(x.description||'')}"></label><div class="actions"><button id="raApply" class="primary">تأیید</button><button id="raCancel" class="secondary">لغو</button></div></div>`);$('#raApply').onclick=async()=>{const fields={amount:Number(String($('#raAmount').value).replace(/[,،٬\s]/g,''))||undefined,date:$('#raDate').value,merchant:$('#raMerchant').value,fee:Number(String($('#raFee').value).replace(/[,،٬\s]/g,''))||0,tracking_number:$('#raTracking').value,reference_number:$('#raReference').value,description:$('#raDesc').value};await api(`/api/receipts/${id}/ai-confirm`,{method:'POST',body:{confirm:'APPLY',fields}});toast('اطلاعات فیش پس از تأیید اعمال شد.');closeModal();route(S.page)};$('#raCancel').onclick=closeModal}catch(e){toast(e.message)}
}
async function imageConvert(file,maxSide=1600,quality=.78){const bmp=await createImageBitmap(file),scale=Math.min(1,maxSide/Math.max(bmp.width,bmp.height)),w=Math.max(1,Math.round(bmp.width*scale)),h=Math.max(1,Math.round(bmp.height*scale));const c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(bmp,0,0,w,h);const webp=await new Promise(r=>c.toBlob(r,'image/webp',quality));const ts=Math.min(1,300/Math.max(w,h)),tc=document.createElement('canvas');tc.width=Math.max(1,Math.round(w*ts));tc.height=Math.max(1,Math.round(h*ts));tc.getContext('2d').drawImage(c,0,0,tc.width,tc.height);const thumb=await new Promise(r=>tc.toBlob(r,'image/webp',.7));return{webp,thumb}}
async function optimizeExistingReceipt(id){const raw=await fetchBlob(`/api/receipts/${id}`),x=await imageConvert(raw,S.settings.receipt_max_side||1600,(S.settings.receipt_quality||78)/100),fd=new FormData();fd.append('file',x.webp,'receipt.webp');fd.append('thumb',x.thumb,'thumb.webp');await api(`/api/receipts/${id}/optimize`,{method:'POST',body:fd})}
async function downloadReceipt(id,fmt){
  let b=await fetchBlob(`/api/receipts/${id}`);
  if(fmt==='webp'&&b.type!=='image/webp'){const x=await imageConvert(b,S.settings.receipt_max_side||1600,(S.settings.receipt_quality||78)/100);b=x.webp}
  if(fmt==='jpg'){const bmp=await createImageBitmap(b),c=document.createElement('canvas');c.width=bmp.width;c.height=bmp.height;c.getContext('2d').drawImage(bmp,0,0);b=await new Promise(r=>c.toBlob(r,'image/jpeg',.9))}
  downloadBlob(b,`receipt-${id}.${fmt}`);
}
function pickReceiptFor(id){const i=document.createElement('input');i.type='file';i.accept='image/*';i.onchange=async()=>{if(!i.files[0])return;try{const x=await imageConvert(i.files[0],S.settings.receipt_max_side||1600,(S.settings.receipt_quality||78)/100),fd=new FormData();fd.append('transaction_id',id);fd.append('file',x.webp,'receipt.webp');fd.append('thumb',x.thumb,'thumb.webp');if(S.settings.keep_original_receipts)fd.append('original',i.files[0],i.files[0].name);await api('/api/receipts',{method:'POST',body:fd});toast('فیش ذخیره شد.');closeModal();transactionDetail(id)}catch(e){toast(e.message)}};i.click()}
async function transactionForm(existing=null){
  await entityMaps();let draft=null;
  if(!existing){const ds=await api('/api/drafts?kind=mini_tx');draft=ds.items[0]||null}
  const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tehran',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
  const st=existing?existing:(draft?JSON.parse(draft.state_json||'{}'):{type:'expense',transaction_date:today,fee_amount:0});
  const recent=(await api('/api/transactions?limit=200')).items.filter(t=>!['refund','transfer','adjustment'].includes(t.type));
  modal(existing?'ویرایش تراکنش':'ثبت تراکنش',`<form id="txForm" class="form">
    <label>نوع<select id="tType" ${existing?'disabled':''}>${['expense','income','transfer','installment_payment','debt','receivable','refund','adjustment'].map(x=>`<option value="${x}" ${st.type===x?'selected':''}>${typeFa(x)}</option>`).join('')}</select></label>
    <label>مبلغ تومان<input id="tAmount" inputmode="numeric" value="${esc(st.amount||'')}"></label>
    <label>دسته<select id="tCategory">${optionRows(S.maps.categories,'category_id','name',st.category_id)}</select></label>
    <label>حساب<select id="tAccount">${optionRows(S.maps.accounts,'account_id','name',st.account_id||S.settings.default_account)}</select></label>
    <label id="destWrap" class="${st.type==='transfer'?'':'hidden'}">حساب مقصد<select id="tDest">${optionRows(S.maps.accounts,'account_id','name',st.destination_account_id)}</select></label>
    <label id="instWrap" class="${st.type==='installment_payment'?'':'hidden'}">برنامه قسط<select id="tInstallment">${optionRows(S.maps.installments,'installment_id','title',st.installment_id||safeMeta(st).installment_id)}</select></label>
    <label id="refundWrap" class="${st.type==='refund'?'':'hidden'}">تراکنش اصلی<select id="tParent">${optionRows(recent,'transaction_id','description',st.parent_transaction_id)}</select></label>
    <label>تاریخ<input id="tDate" value="${esc(st.transaction_date||st.transaction_date_iso||today)}"></label><small class="muted">امروز، دیروز، ۱۴۰۵/۰۵/۱۸ یا 2026-08-09 قابل قبول است.</small>
    <label>توضیح<input id="tDesc" value="${esc(st.description||'')}"></label>
    <details class="details-toggle" ${st.person_id||st.project_id||st.fee_amount?'open':''}><summary>جزئیات بیشتر</summary>
      <label>شخص<select id="tPerson">${optionRows(S.maps.people,'person_id','name',st.person_id)}</select></label>
      <label>پروژه<select id="tProject">${optionRows(S.maps.projects,'project_id','name',st.project_id)}</select></label>
      <label>فروشنده<select id="tMerchant">${optionRows(S.maps.merchants,'merchant_id','name',st.merchant_id)}</select></label>
      <label>برچسب‌ها<select id="tTags" multiple size="4">${S.maps.tags.map(x=>`<option value="${esc(x.tag_id)}" ${(st.tag_ids||[]).includes(x.tag_id)?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>
      <label>کارمزد تومان<input id="tFee" inputmode="numeric" value="${esc(st.fee_amount||0)}"></label>
      <label>شرح کارمزد<input id="tFeeNote" value="${esc(st.fee_note||'')}"></label>
      <label>یادداشت<textarea id="tNote">${esc(st.note||'')}</textarea></label>
      <label>شماره پیگیری<input id="tTracking" value="${esc(st.tracking_number||'')}"></label>
      <label>شماره مرجع<input id="tReference" value="${esc(st.reference_number||'')}"></label>
      <label>فیش<input id="tReceipts" type="file" accept="image/*" multiple></label>
    </details>
    <div class="actions"><button class="primary" type="submit">پیش‌نمایش</button>${draft&&!existing?'<button id="discardDraft" class="danger" type="button">حذف پیش‌نویس</button>':''}</div>
  </form><div id="txPreview" class="hidden"></div>`);
  const toggleType=()=>{const t=$('#tType').value;$('#destWrap').classList.toggle('hidden',t!=='transfer');$('#instWrap').classList.toggle('hidden',t!=='installment_payment');$('#refundWrap').classList.toggle('hidden',t!=='refund')};$('#tType').onchange=toggleType;
  const collect=()=>({type:$('#tType').value,amount:Number(String($('#tAmount').value).replace(/[,،٬\s]/g,''))||0,category_id:$('#tCategory').value,account_id:$('#tAccount').value,destination_account_id:$('#tDest').value,installment_id:$('#tInstallment').value,parent_transaction_id:$('#tParent').value,transaction_date:$('#tDate').value,description:$('#tDesc').value,person_id:$('#tPerson').value,project_id:$('#tProject').value,merchant_id:$('#tMerchant').value,tag_ids:[...$('#tTags').selectedOptions].map(o=>o.value),fee_amount:Number(String($('#tFee').value).replace(/[,،٬\s]/g,''))||0,fee_note:$('#tFeeNote').value,note:$('#tNote').value,tracking_number:$('#tTracking').value,reference_number:$('#tReference').value});
  let saveTimer;if(!existing)$('#txForm').oninput=()=>{clearTimeout(saveTimer);saveTimer=setTimeout(async()=>{const d=await api('/api/drafts',{method:'POST',body:{draft_id:draft?.draft_id,kind:'mini_tx',state:collect()}});draft=d},600)};
  $('#discardDraft')?.addEventListener('click',async()=>{await api(`/api/drafts/${draft.draft_id}`,{method:'DELETE'});closeModal();toast('پیش‌نویس حذف شد.')});
  $('#txForm').onsubmit=e=>{e.preventDefault();const data=collect(),cashRequired=['expense','income','transfer','installment_payment','receivable','refund'].includes(data.type);if(!data.amount||(cashRequired&&!data.account_id)){toast('مبلغ و حساب لازم است.');return}if(data.type==='transfer'&&(!data.destination_account_id||data.destination_account_id===data.account_id)){toast('حساب مقصد معتبر لازم است.');return}if(['receivable','debt'].includes(data.type)&&!data.person_id){toast('برای طلب یا بدهی شخص را انتخاب کنید.');return}if(data.type==='installment_payment'&&!data.installment_id){toast('برنامه قسط را انتخاب کنید.');return}if(data.type==='refund'&&!data.parent_transaction_id){toast('تراکنش اصلی بازپرداخت را انتخاب کنید.');return}showTxPreview(data)};
  function showTxPreview(data){$('#txForm').classList.add('hidden');const p=$('#txPreview');p.classList.remove('hidden');p.innerHTML=`<div class="card"><div class="section-head"><span class="badge">${typeFa(data.type)}</span><b>${money(data.amount)}</b></div><p>${esc(data.description||'بدون شرح')}</p><p class="muted">تاریخ: ${esc(data.transaction_date)}${data.fee_amount?` • کارمزد ${money(data.fee_amount)}`:''}</p></div><div class="actions"><button id="txConfirm" class="primary">✅ تأیید</button><button id="txEditBack" class="secondary">✏️ ویرایش</button><button id="txCancel" class="danger">❌ لغو</button></div>`;$('#txEditBack').onclick=()=>{p.classList.add('hidden');$('#txForm').classList.remove('hidden')};$('#txCancel').onclick=closeModal;$('#txConfirm').onclick=()=>saveTransaction(data)}
  async function saveTransaction(data){try{const tagIds=data.tag_ids;const patch={...data};delete patch.tag_ids;let saved;if(existing){saved=await api(`/api/transactions/${existing.transaction_id}`,{method:'PATCH',body:patch});await api(`/api/transactions/${existing.transaction_id}/tags`,{method:'PUT',body:{tag_ids:tagIds}})}else saved=await api('/api/transactions',{method:'POST',headers:{'x-idempotency-key':crypto.randomUUID()},body:data});const tx=saved.transaction||saved;for(const file of $('#tReceipts').files){const x=await imageConvert(file,S.settings.receipt_max_side||1600,(S.settings.receipt_quality||78)/100),fd=new FormData();fd.append('transaction_id',tx.transaction_id);fd.append('file',x.webp,'receipt.webp');fd.append('thumb',x.thumb,'thumb.webp');if(S.settings.keep_original_receipts)fd.append('original',file,file.name);await api('/api/receipts',{method:'POST',body:fd})}if(draft&&!existing)await api(`/api/drafts/${draft.draft_id}`,{method:'DELETE'});toast('تراکنش ذخیره شد.');closeModal();route(S.page)}catch(err){toast(err.message)}}
}
