async function renderProjects(){const p=await loadEntities('projects');view.innerHTML=`<div class="section-head"><span class="muted">${fa(p.length)} پروژه</span><button id="newProject" class="primary">پروژه جدید</button></div><div class="grid two">${p.map(x=>`<div class="card clickable" data-project="${x.project_id}"><div class="row-icon">${esc(x.icon||'📁')}</div><h3>${esc(x.name)}</h3><p class="muted">${esc(x.description||'')}</p>${x.budget?`<span class="badge">بودجه ${money(x.budget)}</span>`:''}</div>`).join('')||'<div class="empty">پروژه‌ای وجود ندارد.</div>'}</div>`;view.querySelectorAll('[data-project]').forEach(x=>x.onclick=()=>projectDetail(x.dataset.project));$('#newProject').onclick=()=>entityEditor('projects')}
