async function renderReportRange(from,to){
  const r=await api(`/api/reports?from=${encodeURIComponent(from)}&to=${encodeURIComponent(to)}`);
  const days=Math.max(1,Math.round((new Date(to+'T12:00:00Z')-new Date(from+'T12:00:00Z'))/86400000)+1),prevTo=new Date(new Date(from+'T12:00:00Z').getTime()-86400000),prevFrom=new Date(prevTo.getTime()-(days-1)*86400000),iso=d=>d.toISOString().slice(0,10);
  const cmp=await api(`/api/reports/compare?from=${from}&to=${to}&previous_from=${iso(prevFrom)}&previous_to=${iso(prevTo)}`);
  const change=(v,label)=>v===null?`${label}: بدون مبنای مقایسه`:`${label}: ${v>0?'+':''}${fa(v)}٪`;
  view.innerHTML=`<div class="toolbar"><input id="rFrom" type="date" value="${from}"><input id="rTo" type="date" value="${to}"><button id="rApply" class="secondary">اعمال</button></div><section class="grid stats"><div class="card stat"><small>خرج خالص</small><strong>${money(r.summary.net_expense)}</strong></div><div class="card stat"><small>درآمد</small><strong>${money(r.summary.income)}</strong></div><div class="card stat"><small>کارمزد</small><strong>${money(r.summary.fees)}</strong></div><div class="card stat"><small>خالص</small><strong>${money(r.summary.net)}</strong></div></section><div class="card section"><b>مقایسه با بازه قبل</b><p class="muted">${change(cmp.change.expense_pct,'خرج')} • ${change(cmp.change.income_pct,'درآمد')} • ${change(cmp.change.fees_pct,'کارمزد')}</p></div><section class="section card"><div class="section-head"><h2>روند روزانه</h2></div><canvas id="reportChart" class="chart"></canvas></section><section class="section"><div class="section-head"><h2>دسته‌های پرهزینه</h2></div><div class="list">${r.categories.slice(0,10).map(x=>`<div class="row clickable" data-cat="${esc(x.category_id)}"><span>${esc(x.name)}</span><b>${money(x.amount)}</b></div>`).join('')||'<div class="empty">داده‌ای نیست.</div>'}</div></section><div class="actions"><button id="reportCsv" class="secondary">CSV</button><button id="reportXlsx" class="secondary">Excel</button><button id="reportPdf" class="secondary">PDF</button></div>`;
  drawLine($('#reportChart'),Object.values(r.summary.daily||{}));$('#rApply').onclick=()=>renderReportRange($('#rFrom').value,$('#rTo').value);$('#reportCsv').onclick=()=>exportCsv({from,to});$('#reportXlsx').onclick=()=>exportXlsx({from,to});$('#reportPdf').onclick=()=>printTransactions('گزارش مالی',r.transactions);view.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{S.txFilters={from,to,category_id:b.dataset.cat};S.txOffset=0;route('transactions')});
}
