async function manageEntity(name){
  const def=entityDefs[name];if(!def)return;const rows=await loadEntities(name,true),fav=favoriteEntities.has(name),arc=archiveEntities.has(name);
  modal(def.label,`<div class="section-head"><span>${fa(rows.length)} مورد</span><button id="entityNew" class="primary">جدید</button></div><div class="list">${rows.map(x=>`<div class="row"><div><h3>${esc(x.name||x.title||x.scope_type||'مورد')}</h3><p>${arc?(x.archived==='true'?'آرشیوشده':'فعال'):x.enabled==='false'?'غیرفعال':'فعال'} ${fav&&x.favorite==='true'?'• محبوب':''}</p></div><div class="inline">${['accounts','people','projects'].includes(name)?`<button class="ghost detail-entity" data-id="${x[def.id]}">جزئیات</button>`:''}<button class="ghost edit-entity" data-id="${x[def.id]}">ویرایش</button>${fav?`<button class="secondary fav-entity" data-id="${x[def.id]}">${x.favorite==='true'?'☆':'⭐'}</button>`:''}${arc?`<button class="danger arc-entity" data-id="${x[def.id]}">${x.archived==='true'?'بازگردانی':'آرشیو'}</button>`:''}</div></div>`).join('')||'<div class="empty">موردی ثبت نشده است.</div>'}</div>${['categories','people','merchants'].includes(name)?'<div class="actions"><button id="mergeEntity" class="secondary">ادغام دو مورد</button></div>':''}`);
  $('#entityNew').onclick=()=>entityEditor(name);$('#modalBody').querySelectorAll('.edit-entity').forEach(b=>b.onclick=()=>entityEditor(name,rows.find(x=>String(x[def.id])===b.dataset.id)));
  $('#modalBody').querySelectorAll('.detail-entity').forEach(b=>b.onclick=()=>name==='accounts'?accountDetail(b.dataset.id):name==='people'?personDetail(b.dataset.id):projectDetail(b.dataset.id));
  $('#modalBody').querySelectorAll('.arc-entity').forEach(b=>b.onclick=async()=>{const x=rows.find(y=>String(y[def.id])===b.dataset.id);await api(`/api/entities/${name}/${b.dataset.id}/${x.archived==='true'?'restore':'archive'}`,{method:'POST'});manageEntity(name)});
  $('#modalBody').querySelectorAll('.fav-entity').forEach(b=>b.onclick=async()=>{const x=rows.find(y=>String(y[def.id])===b.dataset.id);await api(`/api/entities/${name}/${b.dataset.id}`,{method:'PATCH',body:{favorite:x.favorite!=='true'}});manageEntity(name)});$('#mergeEntity')?.addEventListener('click',()=>mergeUi(name,rows));
}
async function accountDetail(id){
  const [a,balances,tx]=await Promise.all([api(`/api/entities/accounts/${id}`),api('/api/accounts/balances'),api(`/api/accounts/${id}/transactions`)]),balance=balances.items.find(x=>x.account_id===id)?.balance||0;
  modal(a.name,`<section class="grid stats"><div class="card stat"><small>موجودی</small><strong>${money(balance)}</strong></div><div class="card stat"><small>تراکنش</small><strong>${fa(tx.total)}</strong></div></section><section class="section list">${tx.items.slice(0,30).map(txRow).join('')||'<div class="empty">تراکنشی نیست.</div>'}</section><div class="actions"><button id="accountEdit" class="secondary">ویرایش</button><button id="accountPdf" class="ghost">صورتحساب PDF</button></div>`);$('#accountEdit').onclick=()=>entityEditor('accounts',a);$('#accountPdf').onclick=()=>printTransactions(`${a.name} — گردش حساب`,tx.items);$('#modalBody').querySelectorAll('[data-tx]').forEach(x=>x.onclick=()=>transactionDetail(x.dataset.tx));
}
async function personDetail(id){
  await entityMaps();const [p,s]=await Promise.all([api(`/api/entities/people/${id}`),api(`/api/people/${id}/summary`)]);
  modal(p.name,`<section class="grid stats"><div class="card stat"><small>خرج برای شخص</small><strong>${money(s.spent)}</strong></div><div class="card stat"><small>دریافت</small><strong>${money(s.received)}</strong></div><div class="card stat"><small>طلب</small><strong>${money(s.receivable)}</strong></div><div class="card stat"><small>بدهی</small><strong>${money(s.debt)}</strong></div></section><div class="card section"><div class="section-head"><span>مانده</span><strong>${money(s.balance)}</strong></div></div><section class="section"><h3>بدهی و طلب</h3><div class="list">${s.debts.map(d=>`<div class="row"><div><h3>${d.kind==='receivable'?'طلب':'بدهی'}</h3><p>${esc(enumFa(d.status))} ${d.due_date?'• '+esc(d.due_date):''}</p></div><div><b>${money(Math.max(0,Number(d.principal_amount)-Number(d.settled_amount||0)))}</b>${d.status!=='settled'?`<button class="ghost settle-debt" data-id="${d.debt_id}" data-rem="${Math.max(0,Number(d.principal_amount)-Number(d.settled_amount||0))}">تسویه</button>`:''}</div></div>`).join('')||'<div class="empty">مورد بازی نیست.</div>'}</div></section><section class="section"><h3>تراکنش‌ها</h3><div class="list">${s.transactions.slice(0,25).map(txRow).join('')}</div></section><div class="actions"><button id="personEdit" class="secondary">ویرایش</button><button id="personPdf" class="ghost">صورتحساب PDF</button></div>`);
  $('#personEdit').onclick=()=>entityEditor('people',p);$('#personPdf').onclick=()=>printTransactions(`${p.name} — صورتحساب`,s.transactions);$('#modalBody').querySelectorAll('[data-tx]').forEach(x=>x.onclick=()=>transactionDetail(x.dataset.tx));$('#modalBody').querySelectorAll('.settle-debt').forEach(b=>b.onclick=()=>debtSettlementForm(b.dataset.id,Number(b.dataset.rem),id));
}
async function debtSettlementForm(debtId,remaining,personId){
  await entityMaps();modal('ثبت تسویه',`<div class="form"><label>مبلغ<input id="dsAmount" type="number" value="${remaining}"></label><label>حساب<select id="dsAccount">${optionRows(S.maps.accounts,'account_id','name',S.settings.default_account)}</select></label><label>کارمزد<input id="dsFee" type="number" value="0"></label><label>تاریخ<input id="dsDate" value="امروز"></label><label>یادداشت<textarea id="dsNote"></textarea></label><button id="dsSave" class="primary wide">ثبت تسویه</button></div>`);$('#dsSave').onclick=async()=>{await api(`/api/debts/${debtId}/settle`,{method:'POST',body:{amount:Number($('#dsAmount').value),account_id:$('#dsAccount').value,fee_amount:Number($('#dsFee').value||0),date:$('#dsDate').value,note:$('#dsNote').value}});toast('تسویه ثبت شد.');personDetail(personId)};
}
function fieldHtml(f,v){const [key,label,type]=f;if(type.startsWith('select:'))return`<label>${esc(label)}<select data-field="${key}">${type.slice(7).split('|').map(x=>`<option value="${esc(x)}" ${String(v)===x?'selected':''}>${esc(enumFa(x))}</option>`).join('')}</select></label>`;if(type==='textarea')return`<label>${esc(label)}<textarea data-field="${key}">${esc(v||'')}</textarea></label>`;return`<label>${esc(label)}<input data-field="${key}" type="${type==='number'?'number':type==='date'?'date':'text'}" value="${esc(v??'')}"></label>`}
function entityEditor(name,row=null){
  const def=entityDefs[name],fav=favoriteEntities.has(name);modal(`${row?'ویرایش':'ایجاد'} — ${def.label}`,`<div class="form">${def.fields.map(f=>fieldHtml(f,row?.[f[0]])).join('')}${fav?`<label class="inline">محبوب <input id="entityFav" type="checkbox" ${row?.favorite==='true'?'checked':''}></label>`:''}<div class="actions"><button id="saveEntity" class="primary">ذخیره</button></div></div>`);
  $('#saveEntity').onclick=async()=>{const b={};$('#modalBody').querySelectorAll('[data-field]').forEach(el=>{let v=el.value;if(el.type==='number'&&v!=='')v=Number(v);b[el.dataset.field]=v});if(fav)b.favorite=$('#entityFav').checked;try{if(row)await api(`/api/entities/${name}/${row[def.id]}`,{method:'PATCH',body:b});else await api(`/api/entities/${name}`,{method:'POST',body:b});toast('ذخیره شد.');manageEntity(name);if(S.page==='projects')renderProjects()}catch(e){toast(e.message)}};
}
function mergeUi(name,rows){const def=entityDefs[name];modal(`ادغام — ${def.label}`,`<div class="form"><label>مورد اصلی<select id="mergePrimary">${optionRows(rows,def.id,'name')}</select></label><label>مورد تکراری<select id="mergeDup">${optionRows(rows,def.id,'name')}</select></label><p class="muted">تمام ارجاع‌های قابل انتقال به مورد اصلی منتقل می‌شوند و مورد تکراری آرشیو می‌شود.</p><button id="mergeGo" class="danger wide">ادغام با تأیید</button></div>`);$('#mergeGo').onclick=async()=>{const primary_id=$('#mergePrimary').value,duplicate_id=$('#mergeDup').value;if(!primary_id||!duplicate_id||primary_id===duplicate_id){toast('دو مورد متفاوت انتخاب کنید.');return}if(!confirm('ادغام انجام شود؟'))return;try{await api(`/api/merge/${name}`,{method:'POST',body:{primary_id,duplicate_id,confirm:'MERGE'}});toast('ادغام انجام شد.');manageEntity(name)}catch(e){toast(e.message)}}}
async function manageInstallments(){const rows=await loadEntities('installments',true);modal('اقساط',`<div class="section-head"><span>${fa(rows.length)} برنامه</span><button id="newInst" class="primary">قسط جدید</button></div><div class="list">${rows.map(x=>`<div class="row clickable" data-inst="${x.installment_id}"><div><h3>${esc(x.title)}</h3><p>${esc(x.status)}</p></div><b>${money(x.total_amount)}</b></div>`).join('')}</div>`);$('#newInst').onclick=()=>installmentEditor();$('#modalBody').querySelectorAll('[data-inst]').forEach(x=>x.onclick=()=>installmentDetail(x.dataset.inst))}
async function installmentEditor(){
  await entityMaps();modal('قسط جدید',`<div class="form"><label>عنوان<input id="iTitle"></label><label>مبلغ کل<input id="iTotal" type="number"></label><label>تعداد اقساط<input id="iCount" type="number"></label><label>مبلغ پیش‌فرض هر قسط<input id="iDefault" type="number"></label><label>تاریخ شروع<input id="iStart" value="امروز"></label><label>روز سررسید ماه<input id="iDay" type="number" min="1" max="31"></label><label>حساب<select id="iAccount">${optionRows(S.maps.accounts,'account_id','name',S.settings.default_account)}</select></label><label>شخص<select id="iPerson">${optionRows(S.maps.people,'person_id','name')}</select></label><label>پروژه<select id="iProject">${optionRows(S.maps.projects,'project_id','name')}</select></label><label>یادداشت<textarea id="iNote"></textarea></label><button id="iSave" class="primary wide">ذخیره</button></div>`);$('#iSave').onclick=async()=>{const b={title:$('#iTitle').value,total_amount:Number($('#iTotal').value),installment_count:Number($('#iCount').value),default_installment_amount:Number($('#iDefault').value),start_date:$('#iStart').value,due_day:Number($('#iDay').value),account_id:$('#iAccount').value,person_id:$('#iPerson').value,project_id:$('#iProject').value,status:'active',note:$('#iNote').value};await api('/api/entities/installments',{method:'POST',body:b});toast('قسط ذخیره شد.');manageInstallments()};
}
async function installmentDetail(id){
  const s=await api(`/api/installments/${id}/summary`);modal(s.plan.title,`<section class="grid stats"><div class="card stat"><small>پرداخت شده</small><strong>${money(s.paid)}</strong></div><div class="card stat"><small>باقی‌مانده</small><strong>${money(s.remaining)}</strong></div><div class="card stat"><small>کارمزد</small><strong>${money(s.fees)}</strong></div><div class="card stat"><small>دفعات</small><strong>${fa(s.payment_count)} / ${fa(s.plan.installment_count)}</strong></div></section><div class="card section"><p>وضعیت: <b>${esc(s.plan.status)}</b></p><p>روز سررسید: ${fa(s.plan.due_day)}</p></div><div class="section list">${s.payments.map(p=>`<div class="row"><span>${esc(p.payment_date)}</span><b>${money(p.amount)} ${p.fee_amount?`+ ${money(p.fee_amount)}`:''}</b></div>`).join('')||'<div class="empty">پرداختی ثبت نشده است.</div>'}</div><button id="payInst" class="primary wide">ثبت پرداخت</button>`);$('#payInst').onclick=async()=>{await entityMaps();modal('پرداخت قسط',`<div class="form"><label>مبلغ<input id="ipAmount" type="number" value="${s.plan.default_installment_amount}"></label><label>کارمزد<input id="ipFee" type="number" value="0"></label><label>حساب<select id="ipAccount">${optionRows(S.maps.accounts,'account_id','name',s.plan.account_id||S.settings.default_account)}</select></label><label>تاریخ<input id="ipDate" value="امروز"></label><label>یادداشت<textarea id="ipNote"></textarea></label><button id="ipSave" class="primary wide">تأیید پرداخت</button></div>`);$('#ipSave').onclick=async()=>{await api(`/api/installments/${id}/pay`,{method:'POST',body:{amount:Number($('#ipAmount').value),fee_amount:Number($('#ipFee').value),account_id:$('#ipAccount').value,date:$('#ipDate').value,note:$('#ipNote').value}});toast('پرداخت ثبت شد.');installmentDetail(id)}};
}
async function showInbox(){const r=await api('/api/inbox?status=pending&limit=100');modal('صندوق ورودی مالی',`<div class="list">${r.items.map(x=>`<div class="row"><div><h3>${esc(x.title)}</h3><p>${esc(inboxTypeFa(x.type))} • ${esc(x.created_at?.slice(0,16)||'')}</p></div><button class="secondary inbox-done" data-id="${x.inbox_id}">انجام شد</button></div>`).join('')||'<div class="empty">مورد منتظر بررسی وجود ندارد.</div>'}</div>`);$('#modalBody').querySelectorAll('.inbox-done').forEach(b=>b.onclick=async()=>{await api(`/api/inbox/${b.dataset.id}`,{method:'PATCH',body:{status:'done'}});showInbox()})}
async function bankImport(){await entityMaps();modal('ورود صورتحساب بانکی',`<div class="form"><label>حساب<select id="bankAccount">${optionRows(S.maps.accounts,'account_id','name')}</select></label><label>فایل CSV / XLSX / PDF<input id="bankFile" type="file" accept=".csv,.xlsx,.xls,.pdf,text/csv,application/pdf"></label><button id="bankRead" class="primary wide">خواندن فایل</button><div id="bankStage"></div></div>`);$('#bankRead').onclick=async()=>{const file=$('#bankFile').files[0],account=$('#bankAccount').value;if(!file||!account){toast('فایل و حساب را انتخاب کنید.');return}try{const fd=new FormData();fd.append('file',file,file.name);await api('/api/imports/file',{method:'POST',body:fd});let matrix=[];const ext=file.name.split('.').pop().toLowerCase();if(ext==='csv')matrix=parseCsvClient(await file.text());else if(ext==='xlsx'||ext==='xls'){await ensureSheetJs();const wb=XLSX.read(await file.arrayBuffer(),{type:'array'});matrix=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{header:1,raw:false,defval:''})}else if(ext==='pdf'){matrix=await parsePdfClient(file);if(matrix.length<2){$('#bankStage').innerHTML='<p class="warn-text">متن کافی برای ساخت ردیف پیدا نشد.</p><button id="pdfAi" class="secondary wide">استخراج با مدل فایل OpenRouter</button>';$('#pdfAi').onclick=async()=>{const f=new FormData();f.append('file',file,file.name);const x=await api('/api/ai/pdf',{method:'POST',body:f});const fields=['date','amount','description','tracking_number','reference_number','bank_transaction_id','type'],matrix=[fields,...(x.rows||[]).map(r=>fields.map(k=>r[k]??''))];showColumnMapping(file,account,matrix)};return}}showColumnMapping(file,account,matrix)}catch(e){toast(e.message)}}}
function parseCsvClient(text){const rows=[];let row=[],cell='',q=false;for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(q){if(c==='"'&&n==='"'){cell+='"';i++}else if(c==='"')q=false;else cell+=c}else if(c==='"')q=true;else if(c===','){row.push(cell);cell=''}else if(c==='\n'){row.push(cell.replace(/\r$/,''));rows.push(row);row=[];cell=''}else cell+=c}if(cell||row.length){row.push(cell);rows.push(row)}return rows.filter(r=>r.some(x=>String(x).trim()))}
async function ensureSheetJs(){if(window.XLSX)return;await loadScript('https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js')}
function loadScript(src){return new Promise((res,rej)=>{const s=document.createElement('script');s.src=src;s.onload=res;s.onerror=rej;document.head.append(s)})}
async function parsePdfClient(file){try{const pdfjs=await import('https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.min.mjs');pdfjs.GlobalWorkerOptions.workerSrc='https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.worker.min.mjs';const pdf=await pdfjs.getDocument({data:await file.arrayBuffer()}).promise,lines=[];for(let i=1;i<=pdf.numPages;i++){const page=await pdf.getPage(i),tc=await page.getTextContent();lines.push(tc.items.map(x=>x.str).join(' '))}const rows=[['date','amount','description']];for(const line of lines.flatMap(x=>x.split(/\n/))){const dm=line.match(/(\d{4}[\/\-]\d{1,2}[\/\-]\d{1,2})/),nums=[...line.matchAll(/(?:^|\s)(-?[\d,٬،]{3,})(?=\s|$)/g)];if(dm&&nums.length){const amt=nums[nums.length-1][1],desc=line.replace(dm[0],'').replace(nums[nums.length-1][0],' ').trim();rows.push([dm[1],amt,desc])}}return rows}catch{return[]}}
function inferCol(headers,words){const h=headers.map(x=>String(x).toLowerCase());return h.findIndex(x=>words.some(w=>x.includes(w)))}
function showColumnMapping(file,account,matrix){if(!matrix.length){toast('فایل خالی است.');return}const h=matrix[0],select=(id,words)=>`<label>${id}<select data-map="${id}"><option value="-1">—</option>${h.map((x,i)=>`<option value="${i}" ${inferCol(h,words)===i?'selected':''}>${esc(x||`ستون ${i+1}`)}</option>`).join('')}</select></label>`;$('#bankStage').innerHTML=`<h3>تطبیق ستون‌ها</h3><div class="filters">${select('date',['date','تاریخ'])}${select('amount',['amount','مبلغ','برداشت','واریز'])}${select('description',['description','شرح','توضیح'])}${select('tracking_number',['tracking','پیگیری'])}${select('reference_number',['reference','مرجع'])}${select('bank_transaction_id',['transaction id','شناسه'])}${select('type',['type','نوع'])}</div><button id="bankPreview" class="primary wide">بررسی تکراری‌ها</button>`;$('#bankPreview').onclick=async()=>{const map={};$('#bankStage').querySelectorAll('[data-map]').forEach(x=>map[x.dataset.map]=Number(x.value));const rows=matrix.slice(1).filter(r=>r.some(x=>String(x).trim())).map((r,i)=>({row_index:i+2,date:r[map.date]||'',amount:r[map.amount]||'',description:r[map.description]||'',tracking_number:r[map.tracking_number]||'',reference_number:r[map.reference_number]||'',bank_transaction_id:r[map.bank_transaction_id]||'',type:r[map.type]||''}));const p=await api('/api/imports/preview',{method:'POST',body:{file_name:file.name,account_id:account,rows,source:'mini_app'}});showImportReview(p)}}
function showImportReview(p){modal('بررسی ورود بانکی',`<section class="grid stats"><div class="card stat"><small>کل</small><strong>${fa(p.counts.total)}</strong></div><div class="card stat"><small>جدید</small><strong>${fa(p.counts.new)}</strong></div><div class="card stat"><small>تکراری</small><strong>${fa(p.counts.duplicate)}</strong></div><div class="card stat"><small>مشکوک</small><strong>${fa(p.counts.suspect)}</strong></div></section><div class="table-wrap section"><table><thead><tr><th>ردیف</th><th>وضعیت</th><th>مبلغ</th><th>تاریخ</th><th>شرح</th><th>تصمیم</th></tr></thead><tbody>${p.items.map(i=>{const n=JSON.parse(i.normalized_json||'{}');return`<tr><td>${fa(i.row_index)}</td><td>${esc(i.status)}</td><td>${n.amount?money(n.amount):'—'}</td><td>${esc(n.date||'')}</td><td>${esc(n.description||'')}</td><td>${i.status==='suspect'?`<select data-decision="${i.item_id}"><option value="link">اتصال به دستی</option><option value="new">تراکنش جدید</option><option value="skip">رد</option></select>`:i.status==='duplicate'?'قبلاً ثبت شده':i.status==='invalid'?'نامعتبر':'جدید'}</td></tr>`}).join('')}</tbody></table></div><button id="confirmImport" class="primary wide">تأیید ورود</button>`);$('#confirmImport').onclick=async()=>{if(!confirm('موارد جدید ثبت و تصمیم‌های Reconciliation اعمال شوند؟'))return;const decisions={};$('#modalBody').querySelectorAll('[data-decision]').forEach(x=>decisions[x.dataset.decision]=x.value);const x=await api(`/api/imports/${p.import.import_id}/confirm`,{method:'POST',body:{decisions}});toast(`${fa(x.created.length)} تراکنش جدید ثبت شد.`);closeModal();route('transactions')}}
async function splitUi(){const people=await loadEntities('people');modal('محاسبه دنگ',`<div class="form"><label>عنوان<input id="sTitle" value="دنگ"></label><label>مبلغ کل<input id="sTotal" type="number"></label><label>روش<select id="sMode"><option value="equal">سهم مساوی</option><option value="weighted">وزنی</option><option value="custom">سهم مبلغی</option></select></label><div id="splitRows"></div><button id="addSplitRow" class="secondary wide">افزودن نفر</button><button id="calcSplit" class="primary wide">محاسبه قطعی</button><div id="splitResult"></div></div>`);const add=()=>{const d=document.createElement('div');d.className='card section';d.innerHTML=`<label>شخص<select class="spPerson">${optionRows(people,'person_id','name')}</select></label><label>نام برای «من» یا فرد بدون رکورد<input class="spName"></label><label>پرداختی<input class="spPaid" type="number" value="0"></label><label>وزن / سهم سفارشی<input class="spShare" type="number" value="1"></label><button class="danger spDel">حذف ردیف</button>`;d.querySelector('.spDel').onclick=()=>d.remove();$('#splitRows').append(d)};add();add();$('#addSplitRow').onclick=add;$('#calcSplit').onclick=async()=>{const items=[...$('#splitRows').children].map(d=>({person_id:d.querySelector('.spPerson').value,name:d.querySelector('.spName').value||people.find(p=>p.person_id===d.querySelector('.spPerson').value)?.name||'من',paid_amount:Number(d.querySelector('.spPaid').value),share_value:Number(d.querySelector('.spShare').value)})),body={title:$('#sTitle').value,total_amount:Number($('#sTotal').value),mode:$('#sMode').value,items};try{const c=await api('/api/splits/calculate',{method:'POST',body});$('#splitResult').innerHTML=`<div class="table-wrap section"><table><tr><th>نام</th><th>پرداختی</th><th>سهم</th><th>مانده</th></tr>${c.items.map(x=>`<tr><td>${esc(x.name)}</td><td>${money(x.paid_amount)}</td><td>${money(x.share_amount)}</td><td>${money(x.balance)}</td></tr>`).join('')}</table></div><h3>پیشنهاد تسویه</h3>${c.settlements.map(x=>`<div class="row"><span>${esc(x.from.name)} ← ${esc(x.to.name)}</span><b>${money(x.amount)}</b></div>`).join('')||'<p class="muted">تسویه‌ای لازم نیست.</p>'}<button id="saveSplit" class="secondary wide">ذخیره دنگ</button>`;$('#saveSplit').onclick=async()=>{const saved=await api('/api/splits',{method:'POST',body});toast('دنگ ذخیره شد.');await entityMaps();$('#splitResult').insertAdjacentHTML('beforeend',`<div class="card section"><label>حساب تسویه<select id="splitAccount">${optionRows(S.maps.accounts,'account_id','name',S.settings.default_account)}</select></label><button id="splitConvert" class="secondary wide">تبدیل مانده‌ها به طلب/بدهی</button></div>`);$('#splitConvert').onclick=async()=>{if(!confirm('مانده‌های دنگ به رکوردهای طلب/بدهی تبدیل شوند؟'))return;await api(`/api/splits/${saved.split.split_id}/receivables`,{method:'POST',body:{account_id:$('#splitAccount').value,date:'امروز'}});toast('مانده‌ها تبدیل شدند.')}}}catch(e){toast(e.message)}}}
function aiActionHtml(a){const d=a.data||{},name=({create_transaction:'ثبت تراکنش',edit_transaction:'ویرایش تراکنش',create_person:'ساخت شخص',create_project:'ساخت پروژه',pay_installment:'پرداخت قسط',settle_debt:'تسویه بدهی/طلب'})[a.action]||'اقدام';const bits=[];if(d.type)bits.push(typeFa(d.type));if(d.amount)bits.push(money(d.amount));if(d.description)bits.push(d.description);if(d.name||d.title)bits.push(d.name||d.title);return `<div class="row"><b>${esc(name)}</b><span class="muted">${esc(bits.join(' • '))}</span></div>`}
async function aiUi(){const caps=await api('/api/ai/capabilities');modal('دستیار مالی',`<div class="chips"><span class="badge ${caps.text?'good':'warn'}">متن ${caps.text?'✓':'×'}</span><span class="badge ${caps.vision?'good':'warn'}">تصویر ${caps.vision?'✓':'×'}</span><span class="badge ${caps.audio?'good':'warn'}">صوت ${caps.audio?'✓':'×'}</span><span class="badge ${caps.file?'good':'warn'}">فایل ${caps.file?'✓':'×'}</span></div><div id="aiThread" class="section list"></div><div class="form"><label>پیام<textarea id="aiText"></textarea></label><button id="aiSend" class="primary wide">ارسال</button></div>`);$('#aiSend').onclick=async()=>{const text=$('#aiText').value.trim();if(!text)return;const th=$('#aiThread');th.innerHTML+=`<div class="row"><span>${esc(text)}</span></div>`;$('#aiText').value='';try{const r=await api('/api/ai/ask',{method:'POST',body:{text}});if(r.kind==='actions'){th.innerHTML+=`<div class="card"><b>${fa(r.actions.length)} اقدام پیشنهادی</b><div class="list section">${r.actions.map(aiActionHtml).join('')}</div><div class="actions"><button class="primary" id="aiConfirm">تأیید همه</button><button class="secondary" id="aiCancel">لغو</button></div></div>`;$('#aiConfirm').onclick=async()=>{if(confirm('اقدام‌های پیشنهادی اجرا شوند؟')){await api(`/api/ai/confirm/${r.draft_id}`,{method:'POST'});toast('اقدام‌ها اجرا شدند.')}};$('#aiCancel').onclick=async()=>{await api(`/api/ai/cancel/${r.draft_id}`,{method:'POST'});toast('پیشنهادها لغو شدند.')}}else if(r.kind==='split')th.innerHTML+=`<div class="card">${r.result.settlements.map(x=>`${esc(x.from.name)} ← ${esc(x.to.name)}: ${money(x.amount)}`).join('<br>')}</div>`;else th.innerHTML+=`<div class="card">${esc(r.text||'')}</div>`}catch(e){toast(e.message)}}}
async function systemUi(){
  const [h,s]=await Promise.all([api('/api/health'),api('/api/storage')]);const row=(name,x,detail='')=>`<div class="row"><span>${name}${detail?`<small class="muted"> ${esc(detail)}</small>`:''}</span><b class="${x?'good-text':'warn-text'}">${x?'✅':'⚠️'}</b></div>`;
  modal('سلامت سیستم و ذخیره‌سازی',`<div class="list">${row('Telegram',h.telegram.ok)}${row('Google Sheets',h.google_sheets.ok)}${row(h.storage?.kind==='kv'?'Cloudflare KV':h.storage?.kind==='r2'?'Cloudflare R2':'فضای فایل',h.storage?.ok??h.r2?.ok,(h.storage?.configured??h.r2?.configured)?'':'تنظیم نشده')}${row('OpenRouter',h.openrouter.ok,h.openrouter.configured?'':'تنظیم نشده')}${row(`نسخه ساختار ${h.schema.version}`,h.schema.ok)}</div><section class="grid stats section"><div class="card stat"><small>تراکنش‌ها</small><strong>${fa(s.transactions)}</strong></div><div class="card stat"><small>فیش‌ها</small><strong>${fa(s.receipts)}</strong></div><div class="card stat"><small>پیش‌نویس‌ها</small><strong>${fa(s.drafts)}</strong></div><div class="card stat"><small>فضای فایل</small><strong>${formatBytes(s.storage_bytes??s.r2_bytes)}</strong></div></section><p class="muted">آخرین پشتیبان: ${esc(s.last_backup||'ثبت نشده')}</p><div class="actions"><button id="runSetup" class="primary">اجرای راه‌اندازی / مهاجرت</button><button id="setWebhook" class="secondary">تنظیم Webhook</button></div>`);$('#runSetup').onclick=async()=>{if(!confirm('بررسی اتصال و migration idempotent اجرا شود؟'))return;const r=await api('/api/admin/setup',{method:'POST'});toast(`نسخه ساختار ${r.migration.schema_version} بررسی شد.`);systemUi()};$('#setWebhook').onclick=async()=>{const r=await api('/api/admin/telegram-webhook',{method:'POST'});toast(r?.description||'Webhook تنظیم شد.')};
}
function formatBytes(n){if(n<1024)return`${fa(n)} B`;if(n<1048576)return`${(n/1024).toFixed(1)} KB`;return`${(n/1048576).toFixed(1)} MB`}
async function backupUi(){modal('پشتیبان‌گیری / بازیابی',`<div class="list"><button id="backupJson" class="row clickable">دانلود پشتیبان JSON</button><button id="backupFull" class="row clickable">دانلود پشتیبان کامل همراه فیش‌ها</button><button id="restorePick" class="row clickable">انتخاب پشتیبان JSON یا ZIP برای بازیابی</button></div><p class="muted">بازیابی ابتدا پیش‌نمایش می‌شود و بدون تأیید صریح هیچ داده‌ای نوشته نمی‌شود.</p>`);$('#backupJson').onclick=async()=>downloadBlob(await fetchBlob('/api/backup'),'finance-backup.json');$('#backupFull').onclick=fullBackup;$('#restorePick').onclick=()=>$('#restoreFile').click()}
$('#restoreFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{let backup,zip=null;if(file.name.toLowerCase().endsWith('.zip')){await loadScript('https://cdn.jsdelivr.net/npm/jszip@3.10.1/dist/jszip.min.js');zip=await JSZip.loadAsync(file);const entry=zip.file('backup.json');if(!entry)throw new Error('فایل داده پشتیبان در ZIP پیدا نشد.');backup=JSON.parse(await entry.async('text'))}else backup=JSON.parse(await file.text());const p=await api('/api/restore/preview',{method:'POST',body:backup});modal('پیش‌نمایش بازیابی',`<div class="table-wrap"><table><tr><th>برگه</th><th>ورودی</th><th>جدید</th><th>موجود</th></tr>${Object.entries(p.summary).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${fa(v.incoming)}</td><td>${fa(v.add)}</td><td>${fa(v.update)}</td></tr>`).join('')}</table></div><label class="inline"><input id="restoreOverwrite" type="checkbox"> بازنویسی شناسه‌های موجود</label><p class="muted">فیش‌های همراه فایل فشرده: ${fa(p.receipt_manifest_count)}</p><button id="restoreApply" class="danger wide">تأیید بازیابی</button>`);$('#restoreApply').onclick=async()=>{if(!confirm('بازیابی با پیش‌نمایش نمایش‌داده‌شده اجرا شود؟'))return;const overwrite=$('#restoreOverwrite').checked;for(const [sheet,rows] of Object.entries(backup.entities||{})){if(!Array.isArray(rows)||!rows.length)continue;const part={...backup,entities:{[sheet]:rows}};await api('/api/restore/apply',{method:'POST',body:{backup:part,overwrite,confirm:'RESTORE'}})}if(zip)await restoreZipReceipts(zip,backup.receipt_manifest||[]);toast('بازیابی انجام شد.');closeModal()}}catch(err){toast(err.message)}e.target.value=''};
async function fullBackup(){try{await loadScript('https://cdn.jsdelivr.net/npm/jszip@3.10.1/dist/jszip.min.js');const raw=await fetch('/api/backup',{credentials:'same-origin',headers:headers()}),backup=await raw.json(),zip=new JSZip();if(!raw.ok)throw new Error('ساخت پشتیبان انجام نشد.');zip.file('backup.json',JSON.stringify(backup,null,2));for(const r of backup.receipt_manifest||[]){const ext=r.mime_type==='image/webp'?'webp':r.mime_type==='image/png'?'png':'jpg';try{zip.file(`receipts/${r.receipt_id}/receipt.${ext}`,await fetchBlob(`/api/receipts/${r.receipt_id}`))}catch{}if(r.thumb_key)try{zip.file(`receipts/${r.receipt_id}/thumb.webp`,await fetchBlob(`/api/receipts/${r.receipt_id}?thumb=true`))}catch{}if(r.original_key)try{zip.file(`receipts/${r.receipt_id}/original.bin`,await fetchBlob(`/api/receipts/${r.receipt_id}?original=true`))}catch{}}downloadBlob(await zip.generateAsync({type:'blob'}),`finance-full-backup-${tehranIso()}.zip`)}catch(e){toast('ساخت پشتیبان کامل انجام نشد: '+e.message)}}
async function restoreZipReceipts(zip,manifest){for(const r of manifest){const dir=`receipts/${r.receipt_id}/`,main=Object.keys(zip.files).find(k=>k.startsWith(dir+'receipt.'));if(!main)continue;const fd=new FormData(),mainBlob=await zip.file(main).async('blob');fd.append('file',mainBlob,main.split('/').pop());const th=zip.file(dir+'thumb.webp');if(th)fd.append('thumb',await th.async('blob'),'thumb.webp');const orig=zip.file(dir+'original.bin');if(orig)fd.append('original',await orig.async('blob'),'original.bin');try{await api(`/api/restore/receipts/${r.receipt_id}`,{method:'POST',body:fd})}catch{}}}
async function trashUi(){const r=await api('/api/trash');modal('سطل زباله',`<div class="list">${r.items.map(t=>`<div class="row"><div><h3>${esc(t.description||typeFa(t.type))}</h3><p>${money(t.amount)} • ${esc(t.transaction_date)}</p></div><button class="secondary restoreTx" data-id="${t.transaction_id}">بازگردانی</button><button class="danger permTx" data-id="${t.transaction_id}">حذف دائمی</button></div>`).join('')||'<div class="empty">سطل زباله خالی است.</div>'}</div>`);$('#modalBody').querySelectorAll('.restoreTx').forEach(b=>b.onclick=async()=>{await api(`/api/transactions/${b.dataset.id}/restore`,{method:'POST'});trashUi()});$('#modalBody').querySelectorAll('.permTx').forEach(b=>b.onclick=async()=>{const phrase=`DELETE ${b.dataset.id}`;const entered=prompt(`برای حذف دائمی دقیقاً این عبارت را وارد کنید:\n${phrase}`);if(entered!==phrase)return;await api(`/api/transactions/${b.dataset.id}?permanent=true`,{method:'DELETE',headers:{'x-confirm-permanent-delete':phrase}});trashUi()})}
async function prefsUi(){
  const [s,accounts]=await Promise.all([api('/api/settings'),loadEntities('accounts')]),rp=s.reminder_preferences||{recurring:true,installments:true,debts:true,budgets:true},bt=Array.isArray(s.budget_thresholds)?s.budget_thresholds:[80,90,100];modal('تنظیمات امنیت، هوش مصنوعی، یادآوری و فیش',`<div class="form"><label>مدت نشست<select id="pTimeout"><option value="15m" ${s.session_timeout==='15m'?'selected':''}>۱۵ دقیقه</option><option value="30m" ${s.session_timeout==='30m'?'selected':''}>۳۰ دقیقه</option><option value="1h" ${s.session_timeout==='1h'?'selected':''}>۱ ساعت</option><option value="manual" ${s.session_timeout==='manual'?'selected':''}>تا قفل دستی</option></select></label><label>حساب پیش‌فرض<select id="pAccount">${optionRows(accounts,'account_id','name',s.default_account)}</select></label><label>واحد پیش‌فرض<input value="تومان" disabled></label><label>آستانه بودجه (%)<input id="pBudget" value="${esc(bt.join(','))}"></label><fieldset><legend>یادآوری‌ها</legend><label class="inline">تکرارشونده <input id="prRecurring" type="checkbox" ${rp.recurring!==false?'checked':''}></label><label class="inline">اقساط <input id="prInstallments" type="checkbox" ${rp.installments!==false?'checked':''}></label><label class="inline">بدهی/طلب <input id="prDebts" type="checkbox" ${rp.debts!==false?'checked':''}></label><label class="inline">بودجه <input id="prBudgets" type="checkbox" ${rp.budgets!==false?'checked':''}></label></fieldset><label>مدل متنی OpenRouter<input id="pText" value="${esc(s.openrouter_text_model||'')}"></label><label>مدل تصویر<input id="pVision" value="${esc(s.openrouter_vision_model||'')}"></label><label>مدل صوت<input id="pAudio" value="${esc(s.openrouter_audio_model||'')}"></label><label>مدل فایل<input id="pFile" value="${esc(s.openrouter_file_model||'')}"></label><label>کیفیت WebP (40 تا 95)<input id="pQuality" type="number" min="40" max="95" value="${esc(s.receipt_quality||78)}"></label><label>حداکثر ضلع تصویر<input id="pSide" type="number" min="600" max="2400" value="${esc(s.receipt_max_side||1600)}"></label><label class="inline">نگهداری اصل فیش <input id="pOriginal" type="checkbox" ${s.keep_original_receipts?'checked':''}></label><button id="pSave" class="primary wide">ذخیره تنظیمات</button></div>`);$('#pSave').onclick=async()=>{const thresholds=$('#pBudget').value.split(/[,،]/).map(x=>Number(x.trim())).filter(Number.isFinite);S.settings=await api('/api/settings',{method:'PATCH',body:{session_timeout:$('#pTimeout').value,default_account:$('#pAccount').value,default_currency:'TOMAN',budget_thresholds:thresholds,reminder_preferences:{recurring:$('#prRecurring').checked,installments:$('#prInstallments').checked,debts:$('#prDebts').checked,budgets:$('#prBudgets').checked},openrouter_text_model:$('#pText').value,openrouter_vision_model:$('#pVision').value,openrouter_audio_model:$('#pAudio').value,openrouter_file_model:$('#pFile').value,receipt_quality:Number($('#pQuality').value),receipt_max_side:Number($('#pSide').value),keep_original_receipts:$('#pOriginal').checked}});toast('تنظیمات ذخیره شد.');closeModal()};
}
async function exportMenu(){modal('خروجی بر اساس فیلتر فعلی',`<div class="list"><button id="eCsv" class="row clickable">CSV</button><button id="eXlsx" class="row clickable">Excel واقعی XLSX</button><button id="ePdf" class="row clickable">PDF فارسی RTL</button></div>`);$('#eCsv').onclick=()=>exportCsv(S.txFilters);$('#eXlsx').onclick=()=>exportXlsx(S.txFilters);$('#ePdf').onclick=async()=>{const q=new URLSearchParams(S.txFilters);q.set('limit','200');const r=await api('/api/transactions?'+q);printTransactions('خروجی تراکنش‌ها',r.items)}}
async function exportCsv(filters){const q=new URLSearchParams(filters);downloadBlob(await fetchBlob('/api/export/csv?'+q),'transactions.csv')}
async function exportXlsx(filters){await ensureSheetJs();const q=new URLSearchParams(filters);q.set('limit','200');const r=await api('/api/transactions?'+q),rows=r.items.map(t=>({ID:t.transaction_id,'نوع':typeFa(t.type),'مبلغ تومان':Number(t.amount),'کارمزد':Number(t.fee_amount||0),'تاریخ شمسی':t.transaction_date,'تاریخ ISO':t.transaction_date_iso,'شرح':t.description,'یادداشت':t.note,'پیگیری':t.tracking_number,'مرجع':t.reference_number,'منبع':t.source})),wb=XLSX.utils.book_new(),ws=XLSX.utils.json_to_sheet(rows);XLSX.utils.book_append_sheet(wb,ws,'Transactions');XLSX.writeFile(wb,'transactions.xlsx')}
function printTransactions(title,rows){const w=window.open('','_blank');if(!w){toast('اجازه باز شدن پنجره چاپ داده نشده است.');return}w.document.write(`<!doctype html><html dir="rtl" lang="fa"><head><meta charset="utf-8"><title>${esc(title)}</title><style>body{font-family:Tahoma,Arial;direction:rtl;padding:28px;color:#111}h1{font-size:20px}table{width:100%;border-collapse:collapse;font-size:11px}th,td{border:1px solid #bbb;padding:7px;text-align:right}th{background:#eee}@page{size:A4;margin:12mm}</style></head><body><h1>${esc(title)}</h1><table><tr><th>تاریخ</th><th>نوع</th><th>شرح</th><th>مبلغ</th><th>کارمزد</th></tr>${rows.map(t=>`<tr><td>${esc(t.transaction_date)}</td><td>${esc(typeFa(t.type))}</td><td>${esc(t.description||'')}</td><td>${money(t.amount)}</td><td>${money(t.fee_amount||0)}</td></tr>`).join('')}</table><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}

(async()=>{if(!S.initData){showLogin();$('#loginError').textContent='این Mini App فقط از داخل Telegram قابل ورود است.';return}try{await bootstrap();gate.classList.add('hidden');shell.classList.remove('hidden')}catch{showLogin()}})();
